package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.support.TransactionSynchronizationManager;import java.util.*;import java.math.BigInteger;
/** Real object-ledger phase logic with isolated SQL/proof fixtures; no live storage or mTLS claim. */
class FormalInvocationObjectLedgerTest {
 JdbcTemplate db;FormalInvocationObjectLedger ledger;FormalInvocationOutcomeAuthority.VerifiedOutcome proof;TenantScope scope;String tenant=id(1),actor=id(2),project=id(3),invocation=id(4),dispatch=id(5),write=id(6),artifact=id(7);String hash="a".repeat(64),manifest="b".repeat(64);Object row;
 @BeforeEach void setup()throws Exception{TransactionSynchronizationManager.setActualTransactionActive(true);scope=TenantScope.open(new TenantScope.Identity(tenant,actor,BigInteger.ZERO,BigInteger.ONE,BigInteger.ONE));db=mock(JdbcTemplate.class);var schema=mock(FormalInvocationSchema.class);when(schema.manifestSha256()).thenReturn(manifest);ledger=new FormalInvocationObjectLedger(db,schema,1024);proof=mock(FormalInvocationOutcomeAuthority.VerifiedOutcome.class);when(proof.tenantId()).thenReturn(tenant);when(proof.actorId()).thenReturn(actor);when(proof.projectId()).thenReturn(project);when(proof.invocationId()).thenReturn(invocation);when(proof.attemptId()).thenReturn(dispatch);when(proof.classification()).thenReturn("INTERNAL");when(proof.bytes()).thenReturn("{}".getBytes());when(proof.bindingSha256()).thenReturn(hash);when(proof.schemaRef()).thenReturn("urn:fixed");when(proof.schemaSha256()).thenReturn(hash);
  var type=Class.forName(FormalInvocationObjectLedger.class.getName()+"$Row");var ctor=type.getDeclaredConstructors()[0];ctor.setAccessible(true);row=ctor.newInstance(write,artifact,"formal/"+tenant+"/"+invocation+"/"+write+"/"+artifact,com.ruoyi.medical.contracts.WireValues.sha256("{}".getBytes()),2,"{}","urn:fixed",hash,hash);
  when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenAnswer(call->{String sql=call.getArgument(0);if(sql.contains("FROM formal_invocation_object_intent"))return List.of(row);if(sql.contains("FROM formal_invocation_object_attempt"))return List.of(write);if(sql.contains("FROM formal_invocation_object_state"))return List.of("ATTEMPTED");throw new AssertionError(sql);});
 }
 @AfterEach void close(){scope.close();TransactionSynchronizationManager.clear();}
 @Test void persistedAttemptAlwaysRecoversAndNeverInserts()throws Exception{var attempt=ledger.prepare(proof);assertTrue(attempt.priorAttempt());assertEquals(RuntimeObjectAttempt.TransferMode.RECOVER_ONLY,attempt.claimTransferMode());assertEquals(RuntimeObjectAttempt.TransferMode.RECOVER_ONLY,attempt.claimTransferMode());verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void rollbackStageCannotIgnoreImmutableAttempt(){when(db.query(contains("FROM formal_invocation_object_state"),any(RowMapper.class),any(Object[].class))).thenReturn(List.of("PREPARED"));assertThrows(TenantAccessException.class,()->ledger.prepare(proof));}
 @Test void missingAttemptCannotResetAttemptedWrite(){when(db.query(contains("FROM formal_invocation_object_attempt"),any(RowMapper.class),any(Object[].class))).thenReturn(List.of());assertThrows(TenantAccessException.class,()->ledger.prepare(proof));}
 @Test void changedOutcomeCannotReuseOriginalObjectIntent(){when(proof.bindingSha256()).thenReturn("c".repeat(64));assertThrows(TenantAccessException.class,()->ledger.prepare(proof));verify(db,never()).update(anyString(),any(Object[].class));}
 @Test void proofBytesAreDefensivelyCopied()throws Exception{var attempt=ledger.prepare(proof);var data=attempt.bytes();data[0]=0;assertArrayEquals("{}".getBytes(),attempt.bytes());}
 @Test void transactionIsRequired(){TransactionSynchronizationManager.setActualTransactionActive(false);assertThrows(TenantAccessException.class,()->ledger.prepare(proof));verify(db,never()).query(anyString(),any(RowMapper.class),any(Object[].class));}
 static String id(int n){return "00000000-0000-4000-8000-"+String.format("%012d",n);}
}
